void Solver::bump_var(int var, double coeff) {
    if (coeff == 0.0) return;                         // nothing to do
    // increase activity
    double delta = var_inc * coeff;
    activity[var] += delta;

    // lazy rescaling: only when a single activity exceeds a very high threshold
    const double THRESH = 1e150;   // postpone scaling far beyond normal range
    const double SCALE  = 1e-150;  // corresponding scaling factor

    if (activity[var] > THRESH) {
        // scale down all activities and the increment factor
        for (int i = 1; i <= vars; ++i) activity[i] *= SCALE;
        var_inc *= SCALE;
    }

    // keep VSIDS heap up‑to‑date
    if (vsids.inHeap(var)) vsids.update(var);
}
